		void exposesRetryAfterToTheBrowser() {
			client().get().uri(A_PATH_UNDER_THE_PUBLIC_API)
					.header("Origin", FRONTEND_DEV_ORIGIN)
					.exchange()
					.expectHeader().valueEquals("Access-Control-Expose-Headers", "Retry-After");
		}

		/** An allow-list that accepted anything would pass every test above. */
		@Test
		@DisplayName("a preflight from an unlisted origin is refused")
		void refusesPreflightFromAnUnlistedOrigin() {
			client().options().uri(A_PATH_UNDER_THE_PUBLIC_API)
					.header("Origin", "https://not-our-frontend.example")
					.header("Access-Control-Request-Method", "GET")
					.exchange()
					.expectStatus().isForbidden()
					.expectHeader().doesNotExist("Access-Control-Allow-Origin");
		}

		/**
		 * Credentials off is what keeps CSRF-off safe: no cookie or {@code Authorization}
		 * header rides along on a cross-origin call, so there is no ambient authority for a
		 * forged request to borrow.
		 */
		@Test
		@DisplayName("no credentials ride along on a cross-origin call")
		void allowsNoCredentials() {
			client().options().uri(A_PATH_UNDER_THE_PUBLIC_API)
					.header("Origin", FRONTEND_DEV_ORIGIN)
					.header("Access-Control-Request-Method", "GET")
					.exchange()
					.expectHeader().doesNotExist("Access-Control-Allow-Credentials");
		}
	}
}
package hu.bankmonitor.testsupport;

import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.context.annotation.Import;
import org.springframework.test.web.servlet.client.RestTestClient;

/**
 * Base for tests that need the whole application running on a real port.
 *
 * <p>The configuration lives here rather than being repeated on each subclass for a
 * reason beyond tidiness: Spring caches one application context per distinct
 * configuration, so two classes differing by a single annotation pay two boots. Holding
 * the annotations in one place makes the shared context structural rather than a
 * coincidence the next edit could break.
 *
 * <p>{@code RANDOM_PORT} rather than MockMvc, because the claims these tests make are
 * about the servlet container itself — that a request reaches a listening socket, and
 * what kind of thread Tomcat serves it on. MockMvc would bypass it and prove neither.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Import(ThreadProbeController.class)
public abstract class BootedApplicationTest {

	@LocalServerPort
	private int port;

	/**
	 * A client bound to the running server. {@code TestRestTemplate} is gone in Spring
	 * Boot 4; {@code RestTestClient} is its Spring Framework 7 replacement.
	 */
	protected RestTestClient client() {
		return RestTestClient.bindToServer().baseUrl("http://localhost:" + port).build();
	}
}
package hu.bankmonitor.testsupport;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Reports whether the thread serving the request is a virtual thread.
 *
 * <p>Deliberately outside {@code hu.bankmonitor.payments} so component scan never picks
 * it up on its own: test sources share the runtime classpath, so a {@code @RestController}
 * under the application's base package would silently register itself in every
 * {@code @SpringBootTest} in the suite. {@link BootedApplicationTest} imports it
 * explicitly.
 *
 * <p>Two tests need it: one asks it what kind of thread it is running on, and the OpenAPI
 * spike needs a real controller to exist, since a document with no paths would prove very
 * little.
 */
@RestController
public class ThreadProbeController {

	public static final String PATH = "/api/test-probe/thread";

	@GetMapping(PATH)
	public ThreadReport thread() {
		Thread current = Thread.currentThread();
		return new ThreadReport(current.isVirtual(), current.getName());
	}

	public record ThreadReport(boolean virtual, String name) {
	}
}

